<code>
// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.20;

interface INonfungiblePositionManager {
    function ownerOf(uint256 tokenId) external view returns (address);

    function positions(uint256 tokenId)
        external
        view
        returns (
            uint96 nonce,
            address operator,
            address token0,
            address token1,
            uint24 fee,
            int24 tickLower,
            int24 tickUpper,
            uint128 liquidity,
            uint256 feeGrowthInside0LastX128,
            uint256 feeGrowthInside1LastX128,
            uint128 tokensOwed0,
            uint128 tokensOwed1
        );
}

contract DecoderAndSanitizer {
    error DecoderAndSanitizer__BadPathFormat();

    INonfungiblePositionManager public immutable uniswapV3NonFungiblePositionManager;

    constructor(address _positionManager) {
        uniswapV3NonFungiblePositionManager = INonfungiblePositionManager(_positionManager);
    }

    // ---------------------------------------------------------------------
    // ERC20 style: approve / transfer -> return spender/recipient
    // ---------------------------------------------------------------------
    function approve(address spender, uint256 /*amount*/ )
        external
        pure
        returns (bytes memory addressesFound)
    {
        addressesFound = abi.encodePacked(spender);
    }

    function transfer(address to, uint256 /*amount*/ )
        external
        pure
        returns (bytes memory addressesFound)
    {
        addressesFound = abi.encodePacked(to);
    }

    // ---------------------------------------------------------------------
    // ERC4626 / lending-market style (uint256, address) -> return receiver
    // ---------------------------------------------------------------------
    function deposit(uint256, address receiver) external pure returns (bytes memory addressesFound) {
        addressesFound = abi.encodePacked(receiver);
    }

    function mint(uint256, address receiver) external pure returns (bytes memory addressesFound) {
        addressesFound = abi.encodePacked(receiver);
    }

    function borrow(uint256, address receiver) external pure returns (bytes memory addressesFound) {
        addressesFound = abi.encodePacked(receiver);
    }

    function repay(uint256, address receiver) external pure returns (bytes memory addressesFound) {
        addressesFound = abi.encodePacked(receiver);
    }

    function repayWithShares(uint256, address receiver)
        external
        pure
        returns (bytes memory addressesFound)
    {
        addressesFound = abi.encodePacked(receiver);
    }

    // ---------------------------------------------------------------------
    // ERC4626 withdraw / redeem -> return (receiver, owner)
    // ---------------------------------------------------------------------
    function withdraw(uint256, address receiver, address owner)
        external
        pure
        returns (bytes memory addressesFound)
    {
        addressesFound = abi.encodePacked(receiver, owner);
    }

    function redeem(uint256, address receiver, address owner)
        external
        pure
        returns (bytes memory addressesFound)
    {
        addressesFound = abi.encodePacked(receiver, owner);
    }

    // ---------------------------------------------------------------------
    // burn: no addresses to sanitize
    // ---------------------------------------------------------------------
    function burn(uint256) external pure returns (bytes memory addressesFound) {
        addressesFound = "";
    }

    // ---------------------------------------------------------------------
    // Reward / market management: single address parameter
    // ---------------------------------------------------------------------
    function claimFees(address rewardToken)
        external
        pure
        returns (bytes memory addressesFound)
    {
        addressesFound = abi.encodePacked(rewardToken);
    }

    function claimYield(address rewardToken)
        external
        pure
        returns (bytes memory addressesFound)
    {
        addressesFound = abi.encodePacked(rewardToken);
    }

    function disableController(address account)
        external
        pure
        returns (bytes memory addressesFound)
    {
        addressesFound = abi.encodePacked(account);
    }

    // ---------------------------------------------------------------------
    // Euler-like: (address, address)
    // ---------------------------------------------------------------------
    function enableController(address account, address vault)
        external
        pure
        returns (bytes memory addressesFound)
    {
        addressesFound = abi.encodePacked(account, vault);
    }

    function enableCollateral(address account, address vault)
        external
        pure
        returns (bytes memory addressesFound)
    {
        addressesFound = abi.encodePacked(account, vault);
    }

    function disableCollateral(address account, address vault)
        external
        pure
        returns (bytes memory addressesFound)
    {
        addressesFound = abi.encodePacked(account, vault);
    }

    // ---------------------------------------------------------------------
    // Uniswap V3 NonfungiblePositionManager sanitizers
    // ---------------------------------------------------------------------
    struct DecreaseLiquidityParams {
        uint256 tokenId;
        uint128 liquidity;
        uint256 amount0Min;
        uint256 amount1Min;
        uint256 deadline;
    }

    function decreaseLiquidity(DecreaseLiquidityParams calldata params)
        external
        view
        returns (bytes memory addressesFound)
    {
        address owner = uniswapV3NonFungiblePositionManager.ownerOf(params.tokenId);
        addressesFound = abi.encodePacked(owner);
    }

    struct IncreaseLiquidityParams {
        uint256 tokenId;
        uint256 amount0Desired;
        uint256 amount1Desired;
        uint256 amount0Min;
        uint256 amount1Min;
        uint256 deadline;
    }

    function increaseLiquidity(IncreaseLiquidityParams calldata params)
        external
        view
        returns (bytes memory addressesFound)
    {
        address owner = uniswapV3NonFungiblePositionManager.ownerOf(params.tokenId);
        (, , address token0, address token1, uint24 fee, , , , , , , ) =
            uniswapV3NonFungiblePositionManager.positions(params.tokenId);
        // Pack owner + tokens + fee (padded as 20 bytes)
        bytes20 feeBytes = bytes20(uint160(fee) << 136);
        addressesFound = abi.encodePacked(owner, token0, token1, feeBytes);
    }

    struct MintParams {
        address token0;
        address token1;
        uint24 fee;
        int24 tickLower;
        int24 tickUpper;
        uint256 amount0Desired;
        uint256 amount1Desired;
        uint256 amount0Min;
        uint256 amount1Min;
        address recipient;
        uint256 deadline;
    }

    function mint(MintParams calldata params)
        external
        pure
        returns (bytes memory addressesFound)
    {
        addressesFound = abi.encodePacked(params.token0, params.token1, params.recipient);
    }

    struct CollectParams {
        uint256 tokenId;
        address recipient;
        uint128 amount0Max;
        uint128 amount1Max;
    }

    function collect(CollectParams calldata params)
        external
        view
        returns (bytes memory addressesFound)
    {
        address owner = uniswapV3NonFungiblePositionManager.ownerOf(params.tokenId);
        addressesFound = abi.encodePacked(params.recipient, owner);
    }

    // ---------------------------------------------------------------------
    // Uniswap V3 SwapRouter exactInput: extract all tokens from path
    // path format: (token(20) + fee(3))* + token(20)  =>  length % 23 == 20
    // ---------------------------------------------------------------------
    struct ExactInputParams {
        bytes path;
        address recipient;
        uint256 deadline;
        uint256 amountIn;
        uint256 amountOutMinimum;
    }

    function exactInput(ExactInputParams calldata params)
        external
        pure
        returns (bytes memory addressesFound)
    {
        bytes calldata path = params.path;
        uint256 pathLength = path.length;
        if (pathLength % 23 != 20) {
            revert DecoderAndSanitizer__BadPathFormat();
        }

        uint256 hopCount = pathLength / 23;
        uint256 tokenCount = hopCount + 1;

        for (uint256 i = 0; i < tokenCount; i++) {
            address token = _decodePathToken(path, i * 23);
            addressesFound = abi.encodePacked(addressesFound, token);
        }

        addressesFound = abi.encodePacked(addressesFound, params.recipient);
    }

    function _decodePathToken(bytes calldata path, uint256 offset)
        private
        pure
        returns (address token)
    {
        assembly {
            token := shr(96, calldataload(add(path.offset, offset)))
        }
    }

    // ---------------------------------------------------------------------
    // Selector 0xda3ef9d2 - no address extraction required (no-op)
    // ---------------------------------------------------------------------
    function noSanitize0xda3ef9d2() external pure returns (bytes memory addressesFound) {
        addressesFound = "";
    }
}
</code>

