<code>
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IAggregatorV3 {
    function latestRoundData()
        external
        view
        returns (
            uint80 roundId,
            int256 answer,
            uint256 startedAt,
            uint256 updatedAt,
            uint80 answeredInRound
        );
}

library Strings {
    bytes16 private constant HEX_DIGITS = "0123456789abcdef";

    function toHexString(uint256 value, uint256 length) internal pure returns (string memory) {
        bytes memory buffer = new bytes(2 * length + 2);
        buffer[0] = "0";
        buffer[1] = "x";
        for (uint256 i = 2 * length + 1; i > 1; --i) {
            buffer[i] = HEX_DIGITS[value & 0xf];
            value >>= 4;
        }
        require(value == 0, "Strings: hex length insufficient");
        return string(buffer);
    }

    function toHexString(address addr) internal pure returns (string memory) {
        return toHexString(uint256(uint160(addr)), 20);
    }
}

library EnumerableSet {
    struct AddressSet {
        address[] _values;
        mapping(address => uint256) _indexes;
    }

    function add(AddressSet storage set, address value) internal returns (bool) {
        if (set._indexes[value] == 0) {
            set._values.push(value);
            set._indexes[value] = set._values.length;
            return true;
        }
        return false;
    }

    function remove(AddressSet storage set, address value) internal returns (bool) {
        uint256 valueIndex = set._indexes[value];
        if (valueIndex != 0) {
            uint256 toDeleteIndex = valueIndex - 1;
            uint256 lastIndex = set._values.length - 1;
            if (toDeleteIndex != lastIndex) {
                address lastValue = set._values[lastIndex];
                set._values[toDeleteIndex] = lastValue;
                set._indexes[lastValue] = valueIndex;
            }
            set._values.pop();
            delete set._indexes[value];
            return true;
        }
        return false;
    }

    function length(AddressSet storage set) internal view returns (uint256) {
        return set._values.length;
    }

    function at(AddressSet storage set, uint256 index) internal view returns (address) {
        return set._values[index];
    }
}

abstract contract AccessControlEnumerable {
    using EnumerableSet for EnumerableSet.AddressSet;

    struct RoleData {
        mapping(address => bool) members;
        bytes32 adminRole;
    }

    // slot 0
    mapping(bytes32 => RoleData) private _roles;
    // slot 1
    mapping(bytes32 => EnumerableSet.AddressSet) private _roleMembers;

    bytes32 public constant DEFAULT_ADMIN_ROLE = 0x00;

    event RoleGranted(bytes32 indexed role, address indexed account, address indexed sender);
    event RoleRevoked(bytes32 indexed role, address indexed account, address indexed sender);

    function supportsInterface(bytes4 interfaceId) public view virtual returns (bool) {
        return
            interfaceId == 0x5a05180f || // IAccessControlEnumerable
            interfaceId == 0x7965db0b || // IAccessControl
            interfaceId == 0x01ffc9a7;   // IERC165
    }

    function hasRole(bytes32 role, address account) public view returns (bool) {
        return _roles[role].members[account];
    }

    function getRoleAdmin(bytes32 role) public view returns (bytes32) {
        return _roles[role].adminRole;
    }

    function hasMinRole(bytes32 role) public view returns (bool) {
        if (hasRole(role, msg.sender)) return true;
        if (role == DEFAULT_ADMIN_ROLE) return false;
        return hasMinRole(getRoleAdmin(role));
    }

    function grantRole(bytes32 role, address account) public {
        _checkRole(getRoleAdmin(role));
        _grantRole(role, account);
    }

    function revokeRole(bytes32 role, address account) public {
        _checkRole(getRoleAdmin(role));
        _revokeRole(role, account);
    }

    function renounceRole(bytes32 role, address account) public {
        require(
            account == msg.sender,
            "AccessControl: can only renounce roles for self"
        );
        _revokeRole(role, account);
    }

    function getRoleMember(bytes32 role, uint256 index) public view returns (address) {
        return _roleMembers[role].at(index);
    }

    function getRoleMemberCount(bytes32 role) public view returns (uint256) {
        return _roleMembers[role].length();
    }

    function _checkRole(bytes32 role) internal view {
        _checkRole(role, msg.sender);
    }

    function _checkRole(bytes32 role, address account) internal view {
        if (!hasRole(role, account)) {
            revert(
                string(
                    abi.encodePacked(
                        "AccessControl: account ",
                        Strings.toHexString(account),
                        " is missing role ",
                        Strings.toHexString(uint256(role), 32)
                    )
                )
            );
        }
    }

    function _grantRole(bytes32 role, address account) internal {
        if (!hasRole(role, account)) {
            _roles[role].members[account] = true;
            _roleMembers[role].add(account);
            emit RoleGranted(role, account, msg.sender);
        }
    }

    function _revokeRole(bytes32 role, address account) internal {
        if (hasRole(role, account)) {
            _roles[role].members[account] = false;
            _roleMembers[role].remove(account);
            emit RoleRevoked(role, account, msg.sender);
        }
    }

    function _setRoleAdmin(bytes32 role, bytes32 adminRole) internal {
        _roles[role].adminRole = adminRole;
    }
}

contract FeeManager is AccessControlEnumerable {
    // slot 2
    address public owner;
    // slot 3
    address public priceFeedAggregator;
    // slot 4
    uint256 public FEE;
    // slot 5
    uint256 public ETH_WEI_FEE;
    // slot 6
    uint256 public CREATOR_SPLIT;
    // slot 7
    uint256 private _slot7;
    // slot 8
    uint256 private _slot8;

    bytes32 public constant MANAGER_ROLE = keccak256("MANAGER_ROLE");

    event OwnerUpdated(address indexed previousOwner, address indexed newOwner);

    modifier onlyManager() {
        require(hasMinRole(MANAGER_ROLE));
        _;
    }

    // 0x13af4035
    function setOwner(address newOwner) external {
        _checkRole(DEFAULT_ADMIN_ROLE);
        require(hasRole(DEFAULT_ADMIN_ROLE, newOwner), "A");
        address old = owner;
        owner = newOwner;
        emit OwnerUpdated(old, newOwner);
    }

    // 0xf9120af6
    function setAggregator(address _aggregator) external onlyManager {
        priceFeedAggregator = _aggregator;
    }

    // 0x69fe0e2d
    function setFee(uint256 _fee) external onlyManager {
        FEE = _fee;
    }

    // 0x559e6219
    function setETHWEIFee(uint256 _fee) external onlyManager {
        ETH_WEI_FEE = _fee;
    }

    // 0x674e694f
    function setSplit(uint256 _split) external onlyManager {
        CREATOR_SPLIT = _split;
    }

    // 0x4a40eb15
    function setMinFee(uint256 _value) external onlyManager {
        _slot7 = _value;
    }

    // 0x73497be9
    function setMaxFee(uint256 _value) external onlyManager {
        _slot8 = _value;
    }

    // Getters -- slot 4 (FEE)
    function getFeeSetting() external view returns (uint256) {
        return FEE;
    }

    // Getters -- slot 5 (ETH_WEI_FEE)
    function getETHWEIFeeSetting() external view returns (uint256) {
        return ETH_WEI_FEE;
    }

    // Getters -- slot 6 (CREATOR_SPLIT)
    function getSplitSetting() external view returns (uint256) {
        return CREATOR_SPLIT;
    }

    // Getters -- slot 7
    function MIN_FEE() external view returns (uint256) {
        return _slot7;
    }

    function getMinFeeSetting() external view returns (uint256) {
        return _slot7;
    }

    // Getters -- slot 8
    function MAX_FEE() external view returns (uint256) {
        return _slot8;
    }

    function getMaxFeeSetting() external view returns (uint256) {
        return _slot8;
    }

    // 0x8e15f473
    function getLatestPrice() public view returns (int256) {
        (, int256 answer, , , ) = IAggregatorV3(priceFeedAggregator).latestRoundData();
        return answer;
    }

    // 0x63e1b131
    function getCurrentTotalFeeInETH() public view returns (uint256) {
        int256 price = getLatestPrice();
        require(price > 0, "Invalid price data");
        return ((FEE * 1e18) / uint256(price)) * 1e6;
    }

    // 0x8f1a9e35
    function getCurrentCreatorFeeInETH() external view returns (uint256) {
        return (getCurrentTotalFeeInETH() * CREATOR_SPLIT) / 10000;
    }
}
</code>

