// SPDX-License-Identifier: MIT
pragma solidity 0.6.12;

interface IYou {
    function mint(address to, uint256 amount) external returns (bool);
}

contract YouSwap {
    // Storage layout (matches assembly slot order)
    address public owner;                                    // slot 0
    mapping(address => uint256) internal _privateYouAmount;  // slot 1
    uint256 public startHeightOfPriIDO;                      // slot 2
    uint256 public endHeightOfPriIDO;                        // slot 3
    uint256 public totalUsdtAmountOfPriIDO;                  // slot 4
    uint256 public reservedYouOfPriIDO;                      // slot 5
    bool internal _priTargetReached;                         // slot 6 byte 0
    bool internal _priIDOWithdrawn;                          // slot 6 byte 1
    mapping(address => uint256) internal _pubUsdtAmount;     // slot 7
    uint256 public totalUsdtAmountOfPubIDO;                  // slot 8
    uint256 public startHeightOfPubIDO;                      // slot 9
    uint256 public endHeightOfPubIDO;                        // slot 10
    bool internal _pubIDOWithdrawn;                          // slot 11
    mapping(address => bool) internal _whiteList;            // slot 12
    address public youToken;                                 // slot 13
    uint256 internal _unlocked;                              // slot 14

    // Constants
    address internal constant USDT = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address internal constant LP_RECIPIENT = 0x6B5c21A770dA1621Bb28C9A2b6f282e5FC9154D5;

    uint256 internal constant UPPER_LIMIT_PRI = 500000000;          // 500 USDT (6 dec)
    uint256 internal constant BOTTOM_LIMIT_PUB = 100000000;         // 100 USDT
    uint256 internal constant TARGET_USDT_PUB = 50000000000;        // 50,000 USDT
    uint256 internal constant TARGET_YOU_PUB = 500000000000;
    uint256 internal constant SUPPLY_YOU_PRI = 500000000000;
    uint256 internal constant INITIAL_LIQUID_YOU = 3000000000000;

    // Events
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event PublicOffering(address indexed user, uint256 amount);
    event PrivateOffering(address indexed user, uint256 usdtAmount, uint256 youAmount);
    event PrivateOfferingClaimed(address indexed user, uint256 amount);
    event PublicOfferingClaimed(address indexed user, uint256 amount);
    event PublicOfferingRefund(address indexed user, uint256 amount);

    constructor() public {
        owner = msg.sender;
        _unlocked = 1;
        emit OwnershipTransferred(address(0), msg.sender);
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "YouSwap: CALLER_IS_NOT_THE_OWNER");
        _;
    }

    modifier nonReentrant() {
        require(_unlocked == 1, "YouSwap: LOCKED");
        _unlocked = 0;
        _;
        _unlocked = 1;
    }

    // ---------- constant views ----------
    function upperLimitUsdtOfPriIDO() external pure returns (uint256) { return UPPER_LIMIT_PRI; }
    function bottomLimitUsdtOfPubIDO() external pure returns (uint256) { return BOTTOM_LIMIT_PUB; }
    function targetUsdtAmountOfPubIDO() external pure returns (uint256) { return TARGET_USDT_PUB; }
    function initialLiquidYou() external pure returns (uint256) { return INITIAL_LIQUID_YOU; }
    function targetYouAmountOfPubIDO() external pure returns (uint256) { return TARGET_YOU_PUB; }
    function supplyYouForPriIDO() external pure returns (uint256) { return SUPPLY_YOU_PRI; }

    function priOfferingFinished() external view returns (bool) {
        return block.number > endHeightOfPriIDO || _priTargetReached;
    }
    function pubOfferingFinished() external view returns (bool) {
        return block.number > endHeightOfPubIDO;
    }
    function isInWhiteList(address u) external view returns (bool) {
        return _whiteList[u];
    }

    // ---------- ownership ----------
    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "YouSwap: NEW_OWNER_IS_THE_ZERO_ADDRESS");
        emit OwnershipTransferred(owner, newOwner);
        owner = newOwner;
    }

    function renounceOwnership() external onlyOwner {
        emit OwnershipTransferred(owner, address(0));
        owner = address(0);
    }

    // ---------- whitelist management ----------
    function addToWhiteList(address u) external onlyOwner {
        _whiteList[u] = true;
    }

    function removeFromWhiteList(address u) external onlyOwner {
        _whiteList[u] = false;
    }

    function addBatchToWhiteList(address[] calldata users) external onlyOwner {
        for (uint256 i = 0; i < users.length; i++) {
            _whiteList[users[i]] = true;
        }
    }

    // ---------- pub IDO init ----------
    function initPubIDO(uint256 startBlock, uint256 endBlock) external onlyOwner {
        require(
            startHeightOfPubIDO == 0 && startBlock > block.number && endBlock > startBlock,
            "YouSwap:NOT_ALLOWED"
        );
        startHeightOfPubIDO = startBlock;
        endHeightOfPubIDO = endBlock;
    }

    // ---------- private offering ----------
    function privateOffering(uint256 amount) external nonReentrant returns (bool) {
        require(_whiteList[msg.sender], "YouSwap: NOT_IN_WHITE_LIST");
        require(block.number >= startHeightOfPriIDO, "YouSwap:NOT_STARTED_YET");
        require(!_priTargetReached && block.number <= endHeightOfPriIDO, "YouSwap: FORBIDDEN");
        require(_privateYouAmount[msg.sender] == 0, "YouSwap: ENROLLED_ALREADY");
        require(amount <= UPPER_LIMIT_PRI, "YouSwap: EXCEEDS_THE_UPPER_LIMIT");
        require(amount > 0, "YouSwap: INVALID_AMOUNT");
        require(reservedYouOfPriIDO < SUPPLY_YOU_PRI, "YouSwap:INSUFFICIENT_YOU");

        uint256 youAmount = _mul(10, amount);
        uint256 usdtAmount = amount;

        if (_add(youAmount, reservedYouOfPriIDO) > SUPPLY_YOU_PRI) {
            youAmount = _sub(SUPPLY_YOU_PRI, reservedYouOfPriIDO);
            usdtAmount = youAmount / 10;
            _priTargetReached = true;
        }

        _safeTransferFrom(USDT, usdtAmount);
        _privateYouAmount[msg.sender] = youAmount;
        reservedYouOfPriIDO = _add(reservedYouOfPriIDO, youAmount);
        totalUsdtAmountOfPriIDO = _add(totalUsdtAmountOfPriIDO, usdtAmount);

        emit PrivateOffering(msg.sender, usdtAmount, youAmount);
        return true;
    }

    // ---------- public offering ----------
    function publicOffering(uint256 amount) external nonReentrant returns (bool) {
        require(block.number >= startHeightOfPubIDO, "YouSwap: PUB_IDO_NOT_STARTED");
        require(block.number <= endHeightOfPubIDO, "YouSwap: PUBLIC_OFFERING_ENDED");
        require(amount >= BOTTOM_LIMIT_PUB, "YouSwap: 100USDT_AT_LEAST");

        _safeTransferFrom(USDT, amount);
        _pubUsdtAmount[msg.sender] = _add(_pubUsdtAmount[msg.sender], amount);
        totalUsdtAmountOfPubIDO = _add(totalUsdtAmountOfPubIDO, amount);

        emit PublicOffering(msg.sender, amount);
        _whiteList[msg.sender] = true;
        return true;
    }

    // ---------- claim ----------
    function claim() external nonReentrant {
        require(_whiteList[msg.sender], "YouSwap: NOT_IN_WHITE_LIST");

        bool priReady = (block.number >= endHeightOfPriIDO) && (_privateYouAmount[msg.sender] > 0);
        bool pubReady = (block.number >= endHeightOfPubIDO) && (_pubUsdtAmount[msg.sender] > 0);
        require(priReady || pubReady, "YouSwap: FORBIDDEN");

        // private claim
        uint256 priAmount = _privateYouAmount[msg.sender];
        if (block.number >= endHeightOfPriIDO && priAmount > 0) {
            _privateYouAmount[msg.sender] = 0;
            _safeMint(youToken, msg.sender, priAmount);
            emit PrivateOfferingClaimed(msg.sender, priAmount);
        }

        // public claim
        uint256 pubAmount = _pubUsdtAmount[msg.sender];
        if (block.number >= endHeightOfPubIDO && pubAmount > 0) {
            uint256 youAmount;
            if (totalUsdtAmountOfPubIDO > TARGET_USDT_PUB) {
                // over-subscribed: proportional allocation + refund excess USDT
                uint256 usdtShare = _mul(TARGET_USDT_PUB, pubAmount) / totalUsdtAmountOfPubIDO;
                youAmount = _mul(10, usdtShare);
                uint256 refund = _sub(pubAmount, usdtShare);
                if (refund > 0) {
                    _safeTransfer(USDT, msg.sender, refund);
                    emit PublicOfferingRefund(msg.sender, refund);
                }
            } else {
                youAmount = _mul(10, pubAmount);
            }
            _pubUsdtAmount[msg.sender] = 0;
            _safeMint(youToken, msg.sender, youAmount);
            emit PublicOfferingClaimed(msg.sender, youAmount);
        }
    }

    // ---------- owner withdrawals ----------
    function withdrawPubIDO() external onlyOwner {
        require(block.number > endHeightOfPubIDO, "YouSwap: PUB_IDO_NOT_ENDED_YET");
        require(!_pubIDOWithdrawn, "YouSwap: PUB_IDO_WITHDRAWN_ALREADY");

        uint256 amount = totalUsdtAmountOfPubIDO;
        if (amount > TARGET_USDT_PUB) amount = TARGET_USDT_PUB;

        _safeTransfer(USDT, LP_RECIPIENT, amount);
        _safeMint(youToken, LP_RECIPIENT, INITIAL_LIQUID_YOU);
        _pubIDOWithdrawn = true;
    }

    function withdrawPriIDO() external onlyOwner {
        require(block.number > endHeightOfPriIDO, "YouSwap: PRI_IDO_NOT_ENDED_YET");
        require(!_priIDOWithdrawn, "YouSwap: PRI_IDO_WITHDRAWN_ALREADY");

        _safeTransfer(USDT, LP_RECIPIENT, totalUsdtAmountOfPriIDO);
        _priIDOWithdrawn = true;
    }

    // ---------- SafeMath helpers ----------
    function _add(uint256 a, uint256 b) internal pure returns (uint256 c) {
        c = a + b;
        require(c >= a, "SafeMath: addition overflow");
    }
    function _sub(uint256 a, uint256 b) internal pure returns (uint256) {
        require(b <= a, "SafeMath: subtraction overflow");
        return a - b;
    }
    function _mul(uint256 a, uint256 b) internal pure returns (uint256 c) {
        if (a == 0) return 0;
        c = a * b;
        require(c / a == b, "SafeMath: multiplication overflow");
    }

    // ---------- safe token calls ----------
    function _safeTransferFrom(address token, uint256 amount) internal {
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(0x23b872dd, msg.sender, address(this), amount)
        );
        require(
            success && (data.length == 0 || abi.decode(data, (bool))),
            "YouSwap: TRANSFER_FAILED"
        );
    }

    function _safeTransfer(address token, address to, uint256 amount) internal {
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(0xa9059cbb, to, amount)
        );
        require(
            success && (data.length == 0 || abi.decode(data, (bool))),
            "YouSwap: TRANSFER_FAILED"
        );
    }

    function _safeMint(address token, address to, uint256 amount) internal {
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(0x40c10f19, to, amount)
        );
        require(
            success && (data.length == 0 || abi.decode(data, (bool))),
            "YouSwap: TRANSFER_FAILED"
        );
    }
}
