pragma solidity 0.6.12;

interface IFarm {
    function stake(uint256 pid, uint256 amount) external;
    function claim(uint256 pid, uint256 amount) external;
    function transferStaking(uint256 pid) external;
    function getUserReward(uint256 pid)
        external view returns (uint256, uint256, uint256, uint256, uint256);
    function getExMintable(uint256 pid, bytes32 key) external view returns (uint256);
}

interface IJackpot {
    function getCurrentSessionJoined(address user) external view returns (bool);
}

contract PoolManager {
    struct Pool {
        address lpToken;         // slot+0
        uint256 totalStaked;     // slot+1
        uint256 lastRewardBlock; // slot+2
        uint256 accPerShare;     // slot+3
        uint256 tubePid;         // slot+4
        bool    paused;          // slot+5 byte0
        bool    emergency;       // slot+5 byte1
    }

    struct UserInfo {
        uint256 amount;      // slot+0
        uint256 rewardDebt;  // slot+1
        uint256 lastBlock;   // slot+2
        uint256 stakedAt;    // slot+3
    }

    bytes32 private constant EX_MINTABLE_KEY =
        0x080909c18c958ce5a2d36481697824e477319323d03154ceba3b78f28a61887b;
    uint256 private constant DECIMALS = 12;

    mapping(uint256 => Pool) public pools;                                 // slot 0
    mapping(address => uint256[]) private lpTokenPools;                    // slot 1
    mapping(address => mapping(uint256 => UserInfo)) private users;        // slot 2
    address public owner;                                                  // slot 3
    address public tube;                                                   // slot 4  (reward token)
    address public farm;                                                   // slot 5  (staking / chef)
    address public jackpot;                                                // slot 6
    uint256 public poolLength;                                             // slot 7

    event CreatePool(address indexed lpToken, uint256 pid, uint256 tubePid);
    event UpdatePool(uint256 pid, uint256 tubePid, bool paused);
    event UpdateJackpot(address newJackpot);
    event TransferCompany(address oldOwner, address newOwner);
    event Stake(uint256 pid, uint256 amount, address user);
    event Claim(uint256 pid, uint256 amount, uint256 reward, address user);

    modifier onlyOwner() {
        require(msg.sender == owner, "NOT_OWNER");
        _;
    }

    // ---------------- view getters ----------------

    function ownerOf() external view returns (address) { return owner; }

    function getPidByLpToken(address lpToken) external view returns (uint256[] memory) {
        return lpTokenPools[lpToken];
    }

    function getAccTokenInfo(uint256 pid) public view returns (uint256) {
        Pool storage p = pools[pid];
        if (p.totalStaked == 0) return 0;
        uint256 exMintable = IFarm(farm).getExMintable(pid, EX_MINTABLE_KEY);
        (, uint256 pending, , , ) = IFarm(farm).getUserReward(p.tubePid);
        return _divDecimals(_safeAdd(exMintable, pending), p.totalStaked, DECIMALS);
    }

    function getUser(address user, uint256 pid) external view returns (uint256, uint256, uint256) {
        UserInfo storage u = users[user][pid];
        return (u.amount, u.rewardDebt, u.lastBlock);
    }

    function getUserReward(uint256 pid) external view returns (
        uint256 amount, uint256 pending, uint256 lastBlock, uint256 blockNow, uint256 zero_
    ) {
        return _getUserReward(pid, msg.sender);
    }

    function _getUserReward(uint256 pid, address user) internal view returns (
        uint256, uint256, uint256, uint256, uint256
    ) {
        uint256 acc = _safeAdd(pools[pid].accPerShare, getAccTokenInfo(pid));
        UserInfo storage u = users[user][pid];
        uint256 pending = _sub(_mulDecimals(u.amount, acc, DECIMALS), u.rewardDebt);
        return (u.amount, pending, u.lastBlock, block.number, 0);
    }

    // Alternative selector (0x6696a366) reuses same reward calc
    function getUserRewardAt(uint256 pid, address user) external view returns (
        uint256, uint256, uint256, uint256, uint256
    ) {
        return _getUserReward(pid, user);
    }

    // ---------------- admin ----------------

    function createPool(address lpToken, uint256 tubePid) external onlyOwner {
        require(lpToken != address(0), "CREATE_POOL_EMPTY_ADDRESS");
        uint256 pid = poolLength;
        emit CreatePool(lpToken, pid, tubePid);
        Pool storage p = pools[pid];
        p.lpToken = lpToken;
        p.tubePid = tubePid;
        p.lastRewardBlock = block.number;
        lpTokenPools[lpToken].push(pid);
        poolLength = pid + 1;
    }

    function updatePool(uint256 pid, uint256 tubePid, bool paused) external onlyOwner {
        _updateAccPerShare(pid);
        Pool storage p = pools[pid];
        p.tubePid = tubePid;
        p.paused = paused;
        emit UpdatePool(pid, tubePid, paused);
    }

    function updateJackpot(address newJackpot) external onlyOwner {
        jackpot = newJackpot;
        emit UpdateJackpot(newJackpot);
    }

    function transferCompany(address newOwner) external onlyOwner {
        address old = owner;
        owner = newOwner;
        emit TransferCompany(old, newOwner);
    }

    function emergencyCollectToken(address token, uint256 amount) external onlyOwner {
        _safeTransfer(token, owner, amount);
    }

    function emergencyCollectEth(uint256 amount) external onlyOwner {
        _safeTransferETH(owner, amount);
    }

    // ---------------- user ----------------

    function stake(uint256 pid, uint256 amount) external {
        Pool storage p = pools[pid];
        require(p.lpToken != address(0), "STAKE_POOL_NOT_EXIST");
        require(!p.paused, "STAKE_POOL_PAUSED");
        require(!p.emergency, "STAKE_POOL_INACTIVE");

        claim(pid, 0);

        _safeTransferFrom(p.lpToken, msg.sender, address(this), amount);
        _safeApprove(p.lpToken, farm, amount);
        IFarm(farm).stake(p.tubePid, amount);

        p.totalStaked = _safeAdd(p.totalStaked, amount);
        UserInfo storage u = users[msg.sender][pid];
        u.amount = _safeAdd(u.amount, amount);
        u.rewardDebt = _mulDecimals(u.amount, p.accPerShare, DECIMALS);

        emit Stake(pid, amount, msg.sender);
    }

    function claim(uint256 pid, uint256 amount) public {
        Pool storage p = pools[pid];
        require(p.lpToken != address(0), "CLAIM_POOL_NOT_EXIST");
        require(!p.paused, "CLAIM_POOL_PAUSED");
        if (amount > 0) {
            require(!IJackpot(jackpot).getCurrentSessionJoined(msg.sender), "in session");
        }

        _updateAccPerShare(pid);

        uint256 pending = _pendingReward(pid, msg.sender);
        if (pending > 0) {
            _safeTransfer(tube, msg.sender, pending);
            users[msg.sender][pid].lastBlock = block.number;
        }

        if (amount > 0) {
            IFarm(farm).claim(p.tubePid, amount);
            _safeTransfer(p.lpToken, msg.sender, amount);
            UserInfo storage u = users[msg.sender][pid];
            u.amount = _sub(u.amount, amount);
            p.totalStaked = _sub(p.totalStaked, amount);
        }

        if (pending > 0 || amount > 0) {
            emit Claim(pid, amount, pending, msg.sender);
        }
        UserInfo storage uu = users[msg.sender][pid];
        uu.rewardDebt = _mulDecimals(uu.amount, p.accPerShare, DECIMALS);
    }

    // ---------------- internal ----------------

    function _pendingReward(uint256 pid, address user) internal view returns (uint256) {
