    function transferFrom(address sender, address recipient, uint256 amount) public override returns (bool) {
        _transfer(sender, recipient, amount);
        _approve(
            sender,
            _msgSender(),
            _allowances[sender][_msgSender()].sub(amount, "ERC20: transfer amount exceeds allowance")
        );
        return true;
    }

    function _approve(address o, address s, uint256 amount) private {
        require(o != address(0), "ERC20: approve from the zero address");
        require(s != address(0), "ERC20: approve to the zero address");
        _allowances[o][s] = amount;
        emit Approval(o, s, amount);
    }

    function _transfer(address from, address to, uint256 amount) private {
        require(from != address(0), "ERC20: transfer from the zero address");
        require(to != address(0), "ERC20: transfer to the zero address");

        uint256 taxAmount = 0;
        if (from != owner() && to != owner()) {
            if (!_isExcludedFromFee[from]) {
                taxAmount = amount
                    .mul((_buyCount > _reduceBuyTaxAt) ? _finalBuyTax : _initialBuyTax)
                    .div(_denominator);
            }

            if (from == uniswapV2Pair && to != address(uniswapV2Router) && !_isExcludedFromFee[to]) {
                require(amount <= _maxTxAmount, "Exceeds the maxTransaction.");
                require(_balances[to].add(amount) <= _maxWalletAmount, "Exceeds the maxWalletAmount.");
                if (block.number <= launchBlock.add(3)) {
                    require(!isContract(to));
                }
                _buyCount = _buyCount.add(1);
            }

            if (to != uniswapV2Pair && !_isExcludedFromFee[to]) {
                require(_balances[to].add(amount) <= _maxWalletAmount, "Exceeds the maxWalletAmount.");
            }

            if (to == uniswapV2Pair && from != address(this)) {
                if (!_isExcludedFromFee[from]) {
                    taxAmount = amount
                        .mul((_buyCount > _reduceSellTaxAt) ? _finalSellTax : _initialSellTax)
                        .div(_denominator);
                }
            }

            uint256 contractTokenBalance = balanceOf(address(this));
            if (
                !inSwap &&
                to == uniswapV2Pair &&
                swapEnabled &&
                contractTokenBalance > swapTokensMinimum &&
                _buyCount > _preventSwapBefore &&
                !_isExcludedFromFee[from]
            ) {
                swapTokensForEth(min(amount, min(contractTokenBalance, maxFeeSwap)));
                uint256 contractETHBalance = address(this).balance;
                if (contractETHBalance > 0) {
                    sendETHToFee(address(this).balance);
                }
            }
        }

        if (taxAmount > 0) {
            _balances[address(this)] = _balances[address(this)].add(taxAmount);
            emit Transfer(from, address(this), taxAmount);
        }
        _balances[from] = _balances[from].sub(amount);
        _balances[to] = _balances[to].add(amount.sub(taxAmount));
        emit Transfer(from, to, amount.sub(taxAmount));
    }

    function min(uint256 a, uint256 b) private pure returns (uint256) {
        return a > b ? b : a;
    }

    function isContract(address account) private view returns (bool) {
        uint256 size;
        assembly { size := extcodesize(account) }
        return size > 0;
    }

    function removeLimits() external onlyOwner {
        _maxTxAmount = _tTotal;
        _maxWalletAmount = _tTotal;
        emit MaxTransactionAmountUpdated(_tTotal);
    }

    function swapTokensForEth(uint256 tokenAmount) private lockTheSwap {
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = uniswapV2Router.WETH();
        _approve(address(this), address(uniswapV2Router), tokenAmount);
        uniswapV2Router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenAmount,
            0,
            path,
            address(this),
            block.timestamp
        );
    }

    function sendETHToFee(uint256 amount) private {
        _taxWallet.transfer(amount);
    }

    function enableTrading() external onlyOwner {
        require(!tradingOpen, "trading is already open");
        _approve(address(this), address(uniswapV2Router), _tTotal);
        uniswapV2Pair = IUniswapV2Factory(uniswapV2Router.factory())
            .createPair(address(this), uniswapV2Router.WETH());
        uniswapV2Router.addLiquidityETH{value: address(this).balance}(
            address(this),
            balanceOf(address(this)),
            0,
            0,
            owner(),
            block.timestamp
        );
        IERC20(uniswapV2Pair).approve(address(uniswapV2Router), uint256(-1));
        swapEnabled = true;
        tradingOpen = true;
        launchBlock = block.number;
    }

    receive() external payable {}
}
