// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface INFT {
    function mint(address to, uint256 id, uint256 amount) external;
    function mintBatch(address to, uint256[] calldata ids, uint256[] calldata amounts) external;
    function renounceMinter() external;
}

abstract contract Ownable {
    address private _owner;

    error OwnableUnauthorizedAccount(address account);
    error OwnableInvalidOwner(address ownerAddr);

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    constructor(address initialOwner) {
        if (initialOwner == address(0)) revert OwnableInvalidOwner(address(0));
        _transferOwnership(initialOwner);
    }

    modifier onlyOwner() {
        _checkOwner();
        _;
    }

    function owner() public view returns (address) {
        return _owner;
    }

    function _checkOwner() internal view {
        if (owner() != msg.sender) revert OwnableUnauthorizedAccount(msg.sender);
    }

    function renounceOwnership() public onlyOwner {
        _transferOwnership(address(0));
    }

    function transferOwnership(address newOwner) public onlyOwner {
        if (newOwner == address(0)) revert OwnableInvalidOwner(address(0));
        _transferOwnership(newOwner);
    }

    function _transferOwnership(address newOwner) internal {
        address old = _owner;
        _owner = newOwner;
        emit OwnershipTransferred(old, newOwner);
    }
}

abstract contract MinterRole {
    mapping(address => bool) private _minters;

    event MinterAdded(address indexed account);
    event MinterRemoved(address indexed account);

    modifier onlyMinter() {
        require(isMinter(msg.sender), "MinterRole: caller does not have the Minter role");
        _;
    }

    function isMinter(address account) public view returns (bool) {
        require(account != address(0), "Roles: account is the zero address");
        return _minters[account];
    }

    function addMinter(address account) external onlyMinter {
        _addMinter(account);
    }

    function renounceMinter() external {
        _removeMinter(msg.sender);
    }

    function _addMinter(address account) internal {
        require(!_minters[account], "Roles: account already has role");
        _minters[account] = true;
        emit MinterAdded(account);
    }

    function _removeMinter(address account) internal {
        require(_minters[account], "Roles: account does not have role");
        _minters[account] = false;
        emit MinterRemoved(account);
    }
}

contract SaleController is Ownable, MinterRole {
    // ---- Storage layout ----
    // slot 0: Ownable._owner
    // slot 1: MinterRole._minters
    string public contractURI;                                 // slot 2
    uint256 public allowlistSaleStartTime;                     // slot 3
    uint256 public publicSaleStartTime;                        // slot 4
    uint256 public allowlistSalePrice;                         // slot 5
    uint256 public publicSalePrice;                            // slot 6
    uint16 public allowlistSaleLimit;                          // slot 7 (low)
    uint16 public publicSaleLimit;                             // slot 7 (offset 2)
    mapping(uint256 => uint256) private _mintedAmount;         // slot 8
    mapping(uint256 => uint256) private _allowlistMinted;      // slot 9
    mapping(uint256 => uint256) private _publicMinted;         // slot 10
    address public deployer;                                   // slot 11
    INFT public nft;                                           // slot 12

    uint256 private constant PUBLIC_SALE_HARDCAP = 0x018f;

    error NotDeployer();

    event ContractURIUpdated(string previousURI, string newURI);
    event Purchased(address indexed buyer, uint256[] indexed tokenIds, uint256[] amounts);

    constructor(
        address nftAddress,
        uint256 _allowlistStart,
        uint256 _publicStart,
        uint256 _allowlistPrice,
        uint256 _publicPrice,
        uint16 _allowlistLimit,
        uint16 _publicLimit,
        string memory _contractURI
    ) Ownable(msg.sender) {
        nft = INFT(nftAddress);
        deployer = msg.sender;
        allowlistSaleStartTime = _allowlistStart;
        publicSaleStartTime = _publicStart;
        allowlistSalePrice = _allowlistPrice;
        publicSalePrice = _publicPrice;
        allowlistSaleLimit = _allowlistLimit;
        publicSaleLimit = _publicLimit;
        contractURI = _contractURI;
        _addMinter(msg.sender);
    }

    // ---------- View functions ----------

    function getCurrentStageInfo() external view returns (uint256, string memory) {
        if (block.timestamp < allowlistSaleStartTime) {
            return (allowlistSaleStartTime, "Sale not started yet");
        } else if (block.timestamp < publicSaleStartTime) {
            return (publicSaleStartTime, "Allowlist Sale");
        } else {
            return (0, "Public Sale");
        }
    }

    function getCurrentSalePrice() public view returns (uint256) {
        return block.timestamp < publicSaleStartTime ? allowlistSalePrice : publicSalePrice;
    }

    function getMintedAmount(uint256 tokenId) external view returns (uint256) {
        return _mintedAmount[tokenId];
    }

    function getAllowlistMintedByToken(uint256 tokenId) external view returns (uint256) {
        return _allowlistMinted[tokenId];
    }

    function getPublicMintedByToken(uint256 tokenId) external view returns (uint256) {
        return _publicMinted[tokenId];
    }

    // ---------- Admin ----------

    function finalization() external onlyOwner {
        nft.renounceMinter();
    }

    function setContractURI(string calldata newURI) external {
        if (msg.sender != deployer) revert NotDeployer();
        string memory prev = contractURI;
        contractURI = newURI;
        emit ContractURIUpdated(prev, newURI);
    }

    // ---------- Purchase ----------

    function purchase(
        uint256[] calldata tokenIds,
        uint256[] calldata amounts,
        address to
    ) external payable {
        require(block.timestamp >= allowlistSaleStartTime, "Sale is not started yet");

        for (uint256 i = 0; i < tokenIds.length; i++) {
            require(tokenIds[i] >= 1 && tokenIds[i] <= 10, "Invalid tokenId");
        }

        require(_verifyLimits(tokenIds, amounts), "Minting limit exceeded");

        uint256 totalAmount = _sumAmounts(amounts);
        uint256 required = totalAmount * getCurrentSalePrice();
        require(msg.value >= required, "Insufficient funds");

        if (tokenIds.length == 1) {
            nft.mint(to, tokenIds[0], amounts[0]);
            _mintedAmount[tokenIds[0]] += amounts[0];
            _bumpPhaseCounter(tokenIds[0], amounts[0]);
        } else {
            nft.mintBatch(to, tokenIds, amounts);
            for (uint256 i = 0; i < tokenIds.length; i++) {
                _mintedAmount[tokenIds[i]] += amounts[i];
                _bumpPhaseCounter(tokenIds[i], amounts[i]);
            }
        }

        payable(owner()).transfer(msg.value);
        emit Purchased(msg.sender, tokenIds, amounts);
    }

    // ---------- Internal helpers ----------

    function _verifyLimits(
        uint256[] calldata tokenIds,
        uint256[] calldata amounts
    ) internal view returns (bool) {
        require(tokenIds.length == amounts.length, "Array length mismatch");
        uint256 limit = block.timestamp < publicSaleStartTime
            ? uint256(allowlistSaleLimit)
            : PUBLIC_SALE_HARDCAP;

        uint256 sum = 0;
        for (uint256 i = 0; i < tokenIds.length; i++) {
            sum += _mintedAmount[tokenIds[i]] + amounts[i];
            if (sum > limit) {
                return false;
            }
        }
        return true;
    }

    function _sumAmounts(uint256[] calldata amounts) internal pure returns (uint256 s) {
        for (uint256 i = 0; i < amounts.length; i++) {
            s += amounts[i];
        }
    }

    function _bumpPhaseCounter(uint256 tokenId, uint256 amount) internal {
        if (block.timestamp < publicSaleStartTime) {
            _allowlistMinted[tokenId] += amount;
        } else {
            _publicMinted[tokenId] += amount;
        }
    }
}
