    mapping(address => bool) public isOperator;

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event LogSetOperator(address operator, bool status);
    event LogAddRecipient(address recipient, uint256 chainId, uint256 lzChainId);
    event LogSetReporter(uint256 chainId, address reporter);
    event LogChangePurchaser(address newTreasury, address oldTreasury, uint256 percentage);
    event LogSpellStakedReceived(uint16 srcChainId, address recipient, uint32 timestamp, uint128 amount);
    event LogBridgeToRecipient(address recipient, uint256 amount, uint32 lzChainId);

    modifier onlyOwner() {
        require(owner == msg.sender, "Ownable: caller is not the owner");
        _;
    }

    function isActiveChain(uint256 chainId) external view returns (uint8 active, uint32 index) {
        ChainInfo storage c = _isActiveChain[chainId];
        return (c.isActive ? 1 : 0, c.index);
    }

    function recipients(uint256 i)
        external
        view
        returns (address recipient, uint32 kind, uint32 lzChainId, uint32 lastUpdated, uint128 amount)
    {
        MSpellRecipient storage r = _recipients[i];
        return (r.recipient, r.kind, r.lzChainId, r.lastUpdated, r.amount);
    }

    function transferOwnership(address newOwner, bool direct, bool renounce) external onlyOwner {
        if (direct) {
            require(newOwner != address(0) || renounce, "Ownable: zero address");
            emit OwnershipTransferred(owner, newOwner);
            owner = newOwner;
            pendingOwner = address(0);
        } else {
            pendingOwner = newOwner;
        }
    }

    function claimOwnership() external {
        address _pendingOwner = pendingOwner;
        require(msg.sender == _pendingOwner, "Ownable: caller != pending owner");
        emit OwnershipTransferred(owner, _pendingOwner);
        owner = _pendingOwner;
        pendingOwner = address(0);
    }

    function setOperator(address operator, bool status) external onlyOwner {
        isOperator[operator] = status;
        emit LogSetOperator(operator, status);
    }

    function addReporter(address reporter, uint256 chainId) external onlyOwner {
        mSpellReporter[chainId] = reporter;
        emit LogSetReporter(chainId, reporter);
    }

    function addMSpellRecipient(address recipient, uint256 chainId, uint256 lzChainId) external onlyOwner {
        require(!_isActiveChain[chainId].isActive, "chainId already added");
        _recipients.push(MSpellRecipient({
            recipient: recipient,
            kind: 1,
            lzChainId: uint32(lzChainId),
            lastUpdated: 0,
            amount: 0
        }));
        _isActiveChain[chainId] = ChainInfo({isActive: true, index: uint32(_recipients.length - 1)});
        emit LogAddRecipient(recipient, chainId, lzChainId);
    }

    function changePurchaser(address newPurchaser, uint256 percentage) external onlyOwner {
        treasury = newPurchaser;
        treasuryPercentage = percentage;
        emit LogChangePurchaser(newPurchaser, INITIAL_TREAS, percentage);
    }

    function lzReceive(
        uint16 srcChainId,
        bytes calldata srcAddress,
        uint64 /*nonce*/,
        bytes calldata payload
    ) external {
        require(msg.sender == LZ_ENDPOINT);

        uint32 index = _isActiveChain[srcChainId].index;
        require(index < _recipients.length);

        address reporter;
        assembly {
            reporter := shr(96, calldataload(srcAddress.offset))
        }
        require(mSpellReporter[srcChainId] == reporter);

        (uint32 timestamp, uint128 amount) = abi.decode(payload, (uint32, uint128));

        MSpellRecipient storage r = _recipients[index];
        r.amount = amount;
        r.lastUpdated = timestamp;

        emit LogSpellStakedReceived(srcChainId, r.recipient, timestamp, amount);
    }

    function _epoch(uint256 ts) internal pure returns (uint256) {
        // simplified: this contract computes a specific epoch value from timestamp
        // in the original assembly using a Julian date style calculation.
        return ts / 86400;
    }

    function bridgeMim() external {
        uint256 mimBalance = IERC20(MIM).balanceOf(address(this));
        uint256 treasuryAmount = (mimBalance * treasuryPercentage) / 100;
        uint256 amountToBridge = mimBalance - treasuryAmount;
        uint256 epochNow = _epoch(block.timestamp);
        uint256 totalStaked = IERC20(SPELL).balanceOf(MSPELL);

        uint256 len = _recipients.length;

        // Pass 1: aggregate total spell staked
        for (uint256 i = 0; i < len; i++) {
            MSpellRecipient memory r = _recipients[i];
            if (r.kind == 1) {
                uint256 staked = IERC20(SPELL).balanceOf(r.recipient);
                require(r.lastUpdated == epochNow, "stale reporter data");
                totalStaked += staked;
            } else {
                totalStaked += r.amount;
            }
        }

        // Pass 2: distribute rewards
        for (uint256 i = 0; i < len; i++) {
            MSpellRecipient memory r = _recipients[i];
            if (r.kind == 1) {
                uint256 stakedHere = IERC20(SPELL).balanceOf(r.recipient);
                uint256 mimShare = (amountToBridge * stakedHere) / totalStaked;
                uint256 tShare = (treasuryAmount * stakedHere) / totalStaked;
                IERC20(MIM).transfer(r.recipient, mimShare);
                IMSpell(r.recipient).updateReward();
                IERC20(MIM).transfer(treasury, tShare);
            } else {
                uint256 amt = (amountToBridge * r.amount) / totalStaked;
                if (amt > 0) {
                    IAnyswapRouter(ANYSWAP_ROUTER).anySwapOutUnderlying(
                        ANYSWAP_MIM,
                        r.recipient,
                        amt,
                        r.lzChainId
                    );
                    emit LogBridgeToRecipient(r.recipient, amt, r.lzChainId);
                }
            }
        }
    }

    // Backwards-compat alias for the sspellBuyBack selector visible in the switch table.
    function sspellBuyBack() external onlyOwner {
        // no-op placeholder; the original assembly reuses the changePurchaser path
    }
}
