contract NodePayment is Ownable {
    using SafeERC20 for IERC20;

    struct PaymentInfo {
        uint256 amount;
        bool paid;
    }

    IERC20 public immutable nodeToken;

    mapping(uint256 => PaymentInfo) public payments;

    address public platformFeeRecipient;
    uint96 public platformFeeBps;

    uint256 public constant BASIS_POINTS_DIVISOR = 10000;
    uint256 public constant MIN_PAYMENT_AMOUNT = 1e9;
    uint96 public constant MAX_PLATFORM_FEE_BPS = 2000;

    error InvalidAddress();
    error SameValue();
    error FeeTooHigh();
    error InvalidAmount();
    error ArrayLengthMismatch();
    error AlreadyPaid();
    error PaymentTooSmall(uint256 amount);

    event PlatformFeeRecipientUpdated(address indexed oldRecipient, address indexed newRecipient);
    event FeePercentageUpdated(uint96 oldBps, uint96 newBps);
    event Paid(address indexed payer, uint256 indexed id, uint256 indexed amountIn, uint256 netAmount, uint256 fee);
    event Claimed(uint256 indexed id, address indexed recipient, address indexed operator, uint256 amount);

    constructor(address _nodeToken, address _feeRecipient, uint96 _feeBps) {
        require(_nodeToken != address(0), "nodeToken zero");
        require(_feeRecipient != address(0), "recipient zero");
        require(_feeBps <= MAX_PLATFORM_FEE_BPS, "fee too high");
        nodeToken = IERC20(_nodeToken);
        platformFeeRecipient = _feeRecipient;
        platformFeeBps = _feeBps;
    }

    function changePlatformFeeRecipient(address newRecipient) external onlyOwner {
        if (newRecipient == address(0)) revert InvalidAddress();
        address current = platformFeeRecipient;
        if (newRecipient == current) revert SameValue();
        emit PlatformFeeRecipientUpdated(current, newRecipient);
        platformFeeRecipient = newRecipient;
    }

    function changeFeePercentage(uint96 newBps) external onlyOwner {
        uint96 current = platformFeeBps;
        if (newBps == current) revert SameValue();
        if (newBps > MAX_PLATFORM_FEE_BPS) revert FeeTooHigh();
        emit FeePercentageUpdated(current, newBps);
        platformFeeBps = newBps;
    }

    function pay(uint256 id, uint256 amount) external {
        if (amount < MIN_PAYMENT_AMOUNT) revert PaymentTooSmall(amount);

        uint256 fee = (uint256(platformFeeBps) * amount) / BASIS_POINTS_DIVISOR;
        uint256 net = amount - fee;

        payments[id].amount += net;

        nodeToken.safeTransferFrom(msg.sender, address(this), amount);
        if (fee > 0) {
            nodeToken.safeTransfer(platformFeeRecipient, fee);
        }

        emit Paid(msg.sender, id, amount, net, fee);
    }

    function distributePayments(
        uint256[] calldata ids,
        address[] calldata recipients,
        uint256[] calldata amounts
    ) external onlyOwner {
        if (ids.length != recipients.length || ids.length != amounts.length) {
            revert ArrayLengthMismatch();
        }

        for (uint256 i = 0; i < ids.length; i++) {
            uint256 id = ids[i];
            address recipient = recipients[i];
            uint256 amount = amounts[i];

            if (amount == 0) revert InvalidAmount();
            if (recipient == address(0)) revert InvalidAddress();
            if (payments[id].paid) revert AlreadyPaid();

            payments[id].paid = true;

            nodeToken.safeTransfer(recipient, amount);

            emit Claimed(id, recipient, msg.sender, amount);
        }
    }
}
