}

contract ComposablesMarket {
    struct Listing {
        address collection;
        address seller;
        uint256 tokenId;
        uint256 price;
        uint64 fee;
        uint64 maxPerAddress;
        uint64 quantity;
        bool completed;
        bool deleted;
    }

