    mapping(uint256 => mapping(address => uint64)) public perAddressCount;          // slot 203 (0xcb)
    mapping(address => uint256) public balances;                                    // slot 204 (0xcc)
    uint256 private _listingCounter;                                                // slot 205 (0xcd)
    uint256 public listingFee;                                                      // slot 206 (0xce)

    // ---- Events ----
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event Paused(address account);
    event Unpaused(address account);
    event ListingFeeUpdated(uint256 fee);
    event ListingCreated(
        uint256 indexed listingId,
        address indexed seller,
        address collection,
        uint256 tokenId,
        uint256 price,
        uint64 maxPerAddress,
        uint64 quantity
    );
    event ListingFilled(
        uint256 indexed listingId,
        address seller,
        address indexed buyer,
        uint256 tokenId,
        address indexed collection,
        uint256 price,
        uint64 amount,
        uint256 sellerAmount,
        uint256 fee
    );
