    function getListing(uint256 id) external view returns (Listing memory) {
        return _listings[id];
    }

    function listings(uint256 id)
        external
        view
        returns (
            address collection,
            address seller,
            uint256 tokenId,
            uint256 price,
            uint64 fee,
            uint64 maxPerAddress,
            uint64 quantity,
            bool completed,
            bool deleted
        )
