        external
        view
        returns (uint256)
    {
        return _tokenListings[collection][tokenId][index];
    }

    function getTokenListings(address collection, uint256 tokenId)
        external
        view
        returns (uint256[] memory)
    {
        return _tokenListings[collection][tokenId];
    }

    // ---- Create ----
    function createListing(
        address collection,
        uint256 tokenId,
        uint256 price,
        uint64 maxPerAddress,
        uint64 quantity
    ) external whenNotPaused nonReentrant returns (uint256) {
        return _createListing(collection, tokenId, price, maxPerAddress, quantity);
    }

    function createListingBatch(
        address[] calldata collections,
        uint256[] calldata tokenIds,
        uint256[] calldata prices,
        uint64[] calldata maxPerAddresses,
        uint64[] calldata quantities
    ) external whenNotPaused nonReentrant returns (uint256 lastId) {
        for (uint256 i = 0; i < collections.length; i++) {
            lastId = _createListing(
                collections[i],
                tokenIds[i],
                prices[i],
                maxPerAddresses[i],
                quantities[i]
            );
        }
    }

    function _createListing(
        address collection,
        uint256 tokenId,
        uint256 price,
        uint64 maxPerAddress,
        uint64 quantity
    ) internal returns (uint256) {
        require(
            IComposable(collection).owner() == msg.sender,
            "ComposablesMarket: caller must be collection owner"
        );
        require(
            IComposable(collection).minter() == address(this),
            "ComposablesMarket: contract must be collection minter"
        );

        uint256[] storage arr = _tokenListings[collection][tokenId];
        for (uint256 i = 0; i < arr.length; i++) {
            require(
                _listings[arr[i]].deleted,
                "ComposablesMarket: listing already associated to this asset"
            );
        }

        uint256 id = _listingCounter;
        _listings[id] = Listing({
            collection: collection,
            seller: msg.sender,
            tokenId: tokenId,
            price: price,
            fee: 0,
            maxPerAddress: maxPerAddress,
            quantity: quantity,
            completed: false,
            deleted: false
        });
        _tokenListings[collection][tokenId].push(id);

        emit ListingCreated(id, msg.sender, collection, tokenId, price, maxPerAddress, quantity);
        _listingCounter = id + 1;
        return id;
    }

    // ---- Fill ----
    function fillListing(uint256 id, uint64 amount)
        external
        payable
        whenNotPaused
        nonReentrant
    {
        _fillListing(id, amount);
    }

    function fillListingBatch(uint256[] calldata ids, uint64[] calldata amounts)
        external
        payable
        whenNotPaused
        nonReentrant
    {
        for (uint256 i = 0; i < ids.length; i++) {
            _fillListing(ids[i], amounts[i]);
        }
    }

    function _fillListing(uint256 id, uint64 amount) internal {
        Listing storage l = _listings[id];

        uint256 total = l.price * amount;
        require(msg.value == total, "ComposablesMarket: insufficient funds");
        require(!l.deleted, "ComposablesMarket: listing has been removed");
        require(!l.completed, "ComposablesMarket: listing has been completed");

        if (l.maxPerAddress > 0) {
            uint64 next = perAddressCount[id][msg.sender] + amount;
            require(
                next <= l.maxPerAddress,
                "ComposablesMarket: quantity greater than remaining max per address"
            );
            perAddressCount[id][msg.sender] = next;
        }

        if (l.quantity > 0) {
            require(
                amount <= l.quantity,
                "ComposablesMarket: quantity greater than remaining supply"
            );
            uint64 remaining = l.quantity - amount;
            if (remaining == 0) {
                l.completed = true;
            }
        }
        l.quantity = l.quantity - amount;

        uint256 sellerAmt = 0;
        uint256 feeAmt = 0;
        if (l.price > 0) {
            sellerAmt = (uint256(amount) * l.price * (10000 - listingFee)) / 10000;
            feeAmt = (uint256(amount) * l.price * listingFee) / 10000;

            balances[l.seller] += sellerAmt;
            balances[_owner] += feeAmt;
        }

        IComposable(l.collection).mint(msg.sender, l.tokenId, uint256(amount), "");

        emit ListingFilled(
            id,
            l.seller,
            msg.sender,
            l.tokenId,
            l.collection,
            l.price,
            amount,
            sellerAmt,
            feeAmt
        );
    }

    // ---- Delete ----
    function deleteListing(uint256 id) external {
        _deleteListing(id);
    }

    function deleteListingBatch(uint256[] calldata ids) external {
        for (uint256 i = 0; i < ids.length; i++) {
            _deleteListing(ids[i]);
        }
    }

    function _deleteListing(uint256 id) internal {
        Listing storage l = _listings[id];
        require(
            IComposable(l.collection).owner() == msg.sender,
            "ComposablesMarket: caller must be collection owner"
        );
        require(
            IComposable(l.collection).minter() == address(this),
            "ComposablesMarket: contract must be collection minter"
        );
        require(!l.deleted, "ComposablesMarket: listing already deleted");
        l.deleted = true;
        emit ListingDeleted(id, l.seller, l.tokenId);
    }

    // ---- Withdraw ----
    function withdraw(address payable to, uint256 amount)
        external
        whenNotPaused
        nonReentrant
    {
        require(
            amount <= balances[msg.sender],
            "ComposablesMarket: amount greater than balance"
        );
        balances[msg.sender] = balances[msg.sender] - amount;
        to.transfer(amount);
        emit Withdrawal(to, amount);
    }

    receive() external payable {}
}
