    mapping(address => uint256) internal _startTime;                              // 0x6a
    mapping(address => uint256) internal _cliffTime;                              // 0x6b
    mapping(address => uint256) internal _endTime;                                // 0x6c
    mapping(address => InstallmentType) internal _installmentType;                // 0x6d
    mapping(address => bool) public initializedVestor;                            // 0x6e
    mapping(address => bool) public revokedVestor;                                // 0x6f

    uint256 public constant MONTH_SECONDS   = 0x278d00; // 2_592_000  (30 days)
    uint256 public constant QUARTER_SECONDS = 0x77f880; // 7_862_400  (91 days)

    // ERC1967 slots
    bytes32 internal constant _IMPLEMENTATION_SLOT =
        0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
    bytes32 internal constant _ROLLBACK_SLOT =
        0x4910fdfa16fed3260ed0e7147f7cc6da11a60208b5b9406d12a635614ffd9143;

    // Immutable used for UUPS proxy check
    address private immutable __self = address(this);

    event NewMultiSig(address indexed sender, address indexed newMultiSig);
    event Upgraded(address indexed implementation);
    event AdminChanged(address previousAdmin, address newAdmin);

    modifier onlyMultiSig() {
        require(
            msg.sender == multiSig,
            "Vesting::onlyMultiSig: Only multi-signature wallet can call this function"
        );
        _;
    }

    modifier onlyProxy() {
        require(address(this) != __self, "Function must be called through delegatecall");
        require(_getImplementation() == __self, "Function must be called through active proxy");
        _;
    }

    modifier initializer() {
        bool isTopLevelCall = !_initializing;
        require(
            (isTopLevelCall && _initialized < 1) || (!_isConstructor() && _initialized == 1),
            "Initializable: contract is already initialized"
        );
        _initialized = 1;
        if (isTopLevelCall) _initializing = true;
        _;
        if (isTopLevelCall) _initializing = false;
    }

    function _isConstructor() private view returns (bool) {
        return address(this).code.length == 0;
    }

    function initialize(address _nftToken, address _multiSig) external initializer {
        nftToken = _nftToken;
        multiSig = _multiSig;
    }

    // --- Views ---

    function getVestingInfo(address recipient) external view returns (VestingInfo memory info) {
        info.totalAmount        = _totalVesting[recipient];
        info.claimed            = _claimed[recipient];
        info.perInstallment     = _perInstallment[recipient];
        info.startTime          = _startTime[recipient];
        info.cliffTime          = _cliffTime[recipient];
        info.endTime            = _endTime[recipient];
        info.installmentType    = _installmentType[recipient];
        info.revoked            = revokedVestor[recipient];
    }

    function toBeVested(address recipient) external view returns (uint256) {
        require(initializedVestor[recipient], "Vesting::toBeVested: user not in vesting");
        require(!revokedVestor[recipient],    "Vesting::toBeVested: user already revoked");
        return _totalVesting[recipient] - _claimed[recipient];
    }

    function currentClaim(address recipient) external view returns (uint256) {
        require(initializedVestor[recipient], "Vesting::currentClaim: user not in vesting");
        require(!revokedVestor[recipient],    "Vesting::currentClaim: user already revoked");

        if (block.timestamp < _startTime[recipient]) return 0;

        uint256 cliff = _cliffTime[recipient];
        if (block.timestamp < cliff) {
            return _totalVesting[recipient] - _claimed[recipient];
        }

        uint256 interval = _installmentType[recipient] == InstallmentType.MONTHLY
            ? MONTH_SECONDS
            : QUARTER_SECONDS;

        uint256 end = _endTime[recipient];
        uint256 refTime = block.timestamp > end ? end : block.timestamp;
        uint256 installments = (refTime - cliff) / interval + 1;
        uint256 vested = _perInstallment[recipient] * installments;
        uint256 total = _totalVesting[recipient];
        if (vested > total) vested = total;
        return vested - _claimed[recipient];
    }

    // --- Claim ---

    function _computeAndBook(address recipient) internal returns (uint256 amount) {
        if (block.timestamp < _startTime[recipient]) return 0;

        uint256 cliff = _cliffTime[recipient];
        uint256 total = _totalVesting[recipient];

        if (block.timestamp < cliff) {
            amount = total - _claimed[recipient];
            _claimed[recipient] += amount;
            return amount;
        }

        InstallmentType t = _installmentType[recipient];
        uint256 interval;
        if (t == InstallmentType.MONTHLY) {
            interval = MONTH_SECONDS;
        } else if (t == InstallmentType.QUARTERLY) {
            interval = QUARTER_SECONDS;
        } else {
            revert("Vesting::claim: invalid installment");
        }

        uint256 end = _endTime[recipient];
        uint256 refTime = block.timestamp > end ? end : block.timestamp;
        uint256 installments = (refTime - cliff) / interval + 1;
        uint256 vested = _perInstallment[recipient] * installments;
        if (vested > total) vested = total;
        amount = vested - _claimed[recipient];
        _claimed[recipient] += amount;
    }

    function claim(address recipient) public returns (uint256 amount) {
        require(
            msg.sender == recipient || msg.sender == multiSig,
            "Vesting::claim: sender must be a recipient"
        );
        require(initializedVestor[recipient], "Vesting::claim: recipient not in vesting");
        require(!revokedVestor[recipient],    "Vesting::claim: recipient already revoked");

        amount = _computeAndBook(recipient);
        if (amount == 0) return 0;

        require(
            IERC20(nftToken).transfer(recipient, amount),
            "Vesting::claim: failed to transfer remaining tokens"
        );
    }

    function multiClaim(address[] calldata recipients) external {
        require(msg.sender == multiSig,
            "Vesting::onlyMultiSig: Only multi-signature wallet can call this function");
        for (uint256 i = 0; i < recipients.length; i++) {
            claim(recipients[i]);
        }
    }

    // --- Admin ---

    function initializeVesting(
        address[] calldata recipients,
        uint256[] calldata totalAmounts,
        uint256[] calldata perInstallments,
        uint256[] calldata cliffTimes,
        uint256[] calldata endTimes,
        uint8[]   calldata types
    ) external onlyMultiSig {
        require(
            recipients.length == totalAmounts.length &&
            totalAmounts.length == perInstallments.length &&
            perInstallments.length == cliffTimes.length &&
            cliffTimes.length == endTimes.length &&
            endTimes.length == types.length,
            "Vesting::initializeVesting: length of all arrays must be equal"
        );

        uint256 totalToTransfer;

        for (uint256 i = 0; i < recipients.length; i++) {
            address recipient = recipients[i];
            uint256 total     = totalAmounts[i];
            uint256 per       = perInstallments[i];
            uint256 cliff     = cliffTimes[i];
            uint256 end       = endTimes[i];
            uint8   t         = types[i];

            require(recipient != address(0),
                "Vesting::initializeVesting: recipient cannot be the zero address");
            require(!initializedVestor[recipient],
                "Vesting::initializeVesting: user already in vesting");
            require(cliff > block.timestamp,
                "Vesting::initializeVesting: cliff is too early");
            require(end > cliff,
                "Vesting::initializeVesting: end is too early");

            InstallmentType instType;
            if (t == 0) {
                require((end - cliff) % MONTH_SECONDS == 0,
                    "Vesting::initializeVesting: end is too early");
                instType = InstallmentType.MONTHLY;
            } else if (t == 1) {
                require((end - cliff) % QUARTER_SECONDS == 0,
                    "Vesting::initializeVesting: end is too early");
                instType = InstallmentType.QUARTERLY;
            } else {
                revert("Vesting::initializeVesting: installment must be MONTHLY or QUARTERLY");
            }

            _totalVesting[recipient]     = total;
            _perInstallment[recipient]   = per;
            _startTime[recipient]        = block.timestamp;
            _cliffTime[recipient]        = cliff;
            _endTime[recipient]          = end;
            _installmentType[recipient]  = instType;
            initializedVestor[recipient] = true;

            totalToTransfer += total;
        }

        IERC20(nftToken).transferFrom(msg.sender, address(this), totalToTransfer);
    }

    function revokeVesting(address recipient) external onlyMultiSig {
        require(initializedVestor[recipient], "Vesting::claim: recipient not in vesting");
        require(!revokedVestor[recipient],    "Vesting::claim: recipient already revoked");

        // First pay out any currently claimable amount.
        claim(recipient);

        // Mark revoked and return remaining balance to the multiSig.
        revokedVestor[recipient] = true;
        uint256 remaining = _totalVesting[recipient] - _claimed[recipient];

        require(
            IERC20(nftToken).transfer(multiSig, remaining),
            "Vesting::revokeVesting: failed to transfer remaining tokens"
        );
    }

    function changeMultiSig(address newMultiSig) external onlyMultiSig {
        multiSig = newMultiSig;
        emit NewMultiSig(msg.sender, newMultiSig);
    }

    // --- UUPS upgrade logic ---

    function upgradeTo(address newImplementation) external onlyProxy {
        _authorizeUpgrade(newImplementation);
        _upgradeToAndCallUUPS(newImplementation, new bytes(0), false);
    }

    function upgradeToAndCall(address newImplementation, bytes calldata data)
        external
        payable
        onlyProxy
    {
        _authorizeUpgrade(newImplementation);
        _upgradeToAndCallUUPS(newImplementation, data, true);
    }

    function _authorizeUpgrade(address) internal view {
        require(
            msg.sender == multiSig,
            "Vesting::onlyMultiSig: Only multi-signature wallet can call this function"
        );
    }

    function _getImplementation() internal view returns (address impl) {
        bytes32 slot = _IMPLEMENTATION_SLOT;
        assembly { impl := sload(slot) }
    }

    function _setImplementation(address newImpl) private {
        require(newImpl.code.length > 0, "ERC1967: new implementation is not a contract");
        bytes32 slot = _IMPLEMENTATION_SLOT;
        assembly { sstore(slot, newImpl) }
    }

    function _upgradeToAndCallUUPS(address newImpl, bytes memory data, bool forceCall) private {
        // Perform rollback check (simplified)
        bytes32 rollbackSlot = _ROLLBACK_SLOT;
        uint256 rollback;
        assembly { rollback := sload(rollbackSlot) }
        if (rollback != 0) {
            _setImplementation(newImpl);
        } else {
            assembly { sstore(rollbackSlot, 1) }
            (bool ok, ) = newImpl.delegatecall(
                abi.encodeWithSignature("upgradeTo(address)", __self)
            );
            ok; // discard
            assembly { sstore(rollbackSlot, 0) }
            require(
                _getImplementation() == __self,
                "ERC1967Upgrade: upgrade breaks further upgrades"
            );
            _setImplementation(newImpl);
            emit Upgraded(newImpl);
        }

        if (data.length > 0 || forceCall) {
            (bool success, bytes memory ret) = newImpl.delegatecall(data);
            if (!success) {
                if (ret.length > 0) {
                    assembly { revert(add(32, ret), mload(ret)) }
                } else {
                    revert("Address: low-level delegate call failed");
                }
            }
        }
    }
}
